{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate therapy for anxiety, trauma, relationships and life transitions in {{CITY}}, {{STATE}}. Confidential, professional, person-centered care." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="about.html">About</a>
        <a href="specialties.html">Specialties</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">Questions</a>
        <a href="book.html" class="cta small">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero (editorial, high contrast) -->
    <section class="hero">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1 class="eyebrow">A gentle, rigorous space for inner work</h1>
          <h2 class="lead">Therapy that meets you where you are — clarity, steadiness, and practical shifts for real life.</h2>
          <p class="byline">I’m {{THERAPIST_NAME}}, {{LICENSE}} offering short- and long-term treatment rooted in trauma-informed care and somatic awareness. I work with anxiety, relationship patterns, life transitions, and burnout.</p>

          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">About my approach</a>
          </div>

          <p class="small">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="abstract calm illustration" />
          <div class="avatar">
            <img src="assets/img/avatar.svg" alt="avatar" />
            <p class="avatar-by">{{THERAPIST_NAME}}, {{LICENSE}}</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Diagnostic (self-assessment) -->
    <section class="diagnostic wrap" id="diagnostic">
      <h3>Where are you now?</h3>
      <p class="intro">A brief self-check to reflect on what matters most. This is not a diagnosis; it’s a reflective tool to help us target sessions.</p>

      <div class="quiz">
        <button class="accordion">Stress and energy</button>
        <div class="panel">
          <p>Do you find your energy fluctuating severely, or do small tasks feel overwhelming? How are your sleep and appetite?</p>
        </div>

        <button class="accordion">Relationships</button>
        <div class="panel">
          <p>Are you noticing recurring patterns in close relationships, communication breakdowns, or difficulty trusting others?</p>
        </div>

        <button class="accordion">Trauma history</button>
        <div class="panel">
          <p>Have you experienced events that continue to affect your sense of safety, body sensations, or daily functioning?</p>
        </div>
      </div>

      <p class="note">Use your reflections to decide whether an initial consult, targeted short-term work, or ongoing therapy is the right next step.</p>
    </section>

    <!-- Plan (program framing) -->
    <section class="plan wrap" id="plan">
      <h3>Program & sessions</h3>
      <p class="intro">I offer structured pathways tailored to your goals. Each pathway combines reflective conversation, skill-building, and embodied practices.</p>

      <div class="plans-grid">
        <article class="card">
          <h4>Foundation Path (6 sessions)</h4>
          <p>For focused concerns: clarifying goals, tools for regulation, and a short-term plan you can use right away.</p>
          <ul>
            <li>Intake + 5 weekly sessions</li>
            <li>Homework & practical tools</li>
            <li>Email check-ins between sessions</li>
          </ul>
        </article>

        <article class="card">
          <h4>Reflective Series (12 sessions)</h4>
          <p>Deeper exploration of patterns, relational work, and somatic processing to build sustained change.</p>
          <ul>
            <li>Monthly planning & mid-point review</li>
            <li>Integration practices</li>
          </ul>
        </article>

        <article class="card">
          <h4>Ongoing Care (open)</h4>
          <p>Flexible weekly or biweekly sessions for long-term growth, prevention of relapse, and life transitions.</p>
        </article>
      </div>

      <p class="scope">Scope & boundaries: I provide psychotherapy for adults. I do not provide emergency services. If you’re in crisis, please contact local emergency services or your crisis hotline. Confidentiality is explained in intake paperwork.</p>
      <a class="btn primary" href="book.html">Schedule a consult</a>
    </section>

    <!-- Micro habits -->
    <section class="micro-habits wrap" id="micro-habits">
      <h3>Daily micro-practices</h3>
      <p class="intro">Small, consistent practices that support nervous system regulation and clarity.</p>

      <ul class="habits">
        <li><label><input type="checkbox" data-habit="breath" /> 3-minute grounding breath in the morning</label></li>
        <li><label><input type="checkbox" data-habit="movement" /> Gentle 5-minute movement or stretch mid-day</label></li>
        <li><label><input type="checkbox" data-habit="reflection" /> One-minute evening reflection: What went well?</label></li>
      </ul>

      <div class="habit-actions">
        <button class="btn ghost" id="resetHabits">Reset</button>
        <button class="btn" id="saveHabits">Save to local note</button>
      </div>
    </section>

    <!-- Pricing -->
    <section class="pricing wrap" id="pricing">
      <h3>Fees & packages</h3>
      <p class="intro">Transparent options so you can choose what fits your needs. Sliding scale may be available based on limited financial need; please inquire.</p>

      <div class="pricing-grid">
        <div class="price">
          <h4>Intro Consult</h4>
          <p class="amount">30 min • $60</p>
          <p class="desc">A focused 30-minute conversation to see fit and next steps.</p>
        </div>
        <div class="price featured">
          <h4>Standard Session</h4>
          <p class="amount">50 min • $160</p>
          <p class="desc">Full therapy session, in-person or via secure telehealth.</p>
        </div>
        <div class="price">
          <h4>Extended Session</h4>
          <p class="amount">80 min • $230</p>
          <p class="desc">When deeper processing or couples work needs more time.</p>
        </div>
      </div>

      <p class="payment">I accept private pay. I can provide superbills for insurance reimbursement; please check your benefits. Sliding scale openings are limited.</p>
      <a class="btn primary" href="fees.html">Full fee details</a>
    </section>

    <!-- Call to action -->
    <section class="cta wrap">
      <h3>Ready for a steady, compassionate space?</h3>
      <p>If this feels like a fit, let’s start with a brief consult to clarify goals and logistics.</p>
      <div class="cta-actions">
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn ghost" href="contact.html">Contact me</a>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <p class="brand">{{BUSINESS_NAME}}</p>
        <p>{{THERAPIST_NAME}}, {{LICENSE}} — {{MODALITIES}}</p>
        <p>{{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <div>
        <h4>Policies</h4>
        <ul>
          <li><a href="privacy.html">Privacy & confidentiality</a></li>
          <li><a href="terms.html">Terms</a></li>
        </ul>
      </div>
      <div>
        <h4>Quick links</h4>
        <ul>
          <li><a href="book.html">Book a session</a></li>
          <li><a href="specialties.html">Specialties</a></li>
          <li><a href="faq.html">Questions</a></li>
        </ul>
      </div>
    </div>

    <div class="legal wrap">
      <p>Confidentiality note: Clinical notes are stored securely. Communications by email or text are not guaranteed to be secure. Crisis disclaimer: If you are in immediate danger or experiencing a psychiatric emergency, call local emergency services or your crisis line. Scope: I provide psychotherapy for adults; I do not provide legal, medical, or emergency services.</p>
      <p class="small">&copy; {{BUSINESS_NAME}} • All rights reserved.</p>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
