{"path":"assets/css/styles.css","content":"/* Aura editorial — high contrast, bold scale */
:root{
  --bg:#0f1113;
  --muted:#9aa3ad;
  --accent:#ffd58a;
  --panel:#ffffff;
  --card:#f6f7f8;
  --primary:#ffb86b;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family: Georgia, 'Times New Roman', serif; background:var(--bg); color:var(--panel); margin:0; -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--max-width);margin:0 auto;padding:28px}
.site-header{border-bottom:1px solid rgba(255,255,255,0.06);background:linear-gradient(180deg, rgba(255,255,255,0.02), transparent)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--panel);text-decoration:none;font-size:18px}
.nav a{color:var(--muted);margin-left:18px;text-decoration:none;font-size:14px}
.nav a.cta.small{background:var(--primary);color:#000;padding:8px 12px;border-radius:6px;margin-left:18px}
.hero{padding:56px 0;border-bottom:1px solid rgba(255,255,255,0.04)}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:32px;align-items:center}
.hero-copy .eyebrow{font-size:14px;color:var(--accent);letter-spacing:1px;text-transform:uppercase;margin:0 0 12px}
.lead{font-size:36px;line-height:1.05;margin:0 0 18px;color:#fff}
.byline{color:var(--muted);margin-bottom:18px}
.hero-actions .btn{margin-right:12px}
.btn{display:inline-block;padding:12px 18px;border-radius:8px;text-decoration:none;font-weight:600}
.btn.primary{background:var(--primary);color:#100a00}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.08);color:var(--panel)}
.small{font-size:13px;color:var(--muted)}
.hero-art{position:relative}
.hero-art img{width:100%;height:auto;border-radius:8px;background:#fff}
.avatar{position:absolute;bottom:-18px;left:18px;background:rgba(255,255,255,0.95);color:#111;padding:10px 12px;border-radius:10px;display:flex;align-items:center}
.avatar img{width:46px;height:46px;border-radius:50%;margin-right:10px}
.avatar-by{font-size:14px;margin:0}

.diagnostic h3, .plan h3, .micro-habits h3, .pricing h3, .cta h3{color:var(--accent);margin-top:24px}
.diagnostic .intro, .plan .intro, .micro-habits .intro, .pricing .intro{color:var(--muted)}
.quiz{margin-top:16px}
.accordion{background:transparent;color:var(--panel);cursor:pointer;padding:14px;border:1px solid rgba(255,255,255,0.04);width:100%;text-align:left;border-radius:8px;margin-bottom:8px}
.panel{padding:12px 14px;background:rgba(255,255,255,0.02);margin-bottom:8px;border-radius:6px;display:none;color:var(--muted)}
.note{font-size:13px;color:var(--muted);margin-top:8px}

.plans-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.card{background:rgba(255,255,255,0.03);padding:18px;border-radius:10px}
.card h4{margin:0 0 8px;color:#fff}
.card ul{color:var(--muted);margin:8px 0 0;padding-left:18px}
.scope{font-size:12px;color:var(--muted);margin-top:12px}

.micro-habits .habits{list-style:none;padding:0;margin:12px 0}
.micro-habits li{background:rgba(255,255,255,0.02);padding:10px;border-radius:8px;margin-bottom:8px}
.habit-actions{margin-top:10px}

.pricing-grid{display:flex;gap:18px;margin-top:12px}
.price{background:rgba(255,255,255,0.03);padding:16px;border-radius:10px;flex:1}
.price.featured{border:1px solid rgba(255,255,255,0.06);background:linear-gradient(180deg, rgba(255,184,107,0.08), rgba(255,255,255,0.02))}
.amount{font-size:20px;color:#fff;margin:8px 0}
.payment{color:var(--muted);margin-top:10px}

.cta{padding:28px 0;text-align:center}
.cta .btn{margin:8px}

.site-footer{border-top:1px solid rgba(255,255,255,0.04);padding:28px 0;margin-top:36px}
.footer-grid{display:grid;grid-template-columns:1fr 200px 200px;gap:18px}
.brand{font-weight:700}
.legal{margin-top:12px;color:var(--muted);font-size:13px}

@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .plans-grid{grid-template-columns:1fr}
  .pricing-grid{flex-direction:column}
  .footer-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactivity for accordions, habits, and simple booking modal
document.addEventListener('DOMContentLoaded',function(){
  // Accordions
  var acc = document.getElementsByClassName('accordion');
  for(var i=0;i<acc.length;i++){
    acc[i].addEventListener('click',function(){
      this.classList.toggle('active');
      var panel = this.nextElementSibling;
      if(panel.style.display==='block'){panel.style.display='none'}else{panel.style.display='block'}
    });
  }

  // Habits: save to localStorage
  var saveBtn = document.getElementById('saveHabits');
  var resetBtn = document.getElementById('resetHabits');
  function getHabitsState(){
    var checks = document.querySelectorAll('.habits input[type="checkbox"]');
    var state = {};
    checks.forEach(function(c){state[c.dataset.habit]=c.checked});
    return state;
  }
  function restoreHabits(){
    try{
      var raw = localStorage.getItem('micro_habits');
      if(!raw) return;
      var obj = JSON.parse(raw);
      var checks = document.querySelectorAll('.habits input[type="checkbox"]');
      checks.forEach(function(c){c.checked = !!obj[c.dataset.habit]});
    }catch(e){console.warn(e)}
  }
  if(saveBtn){saveBtn.addEventListener('click',function(){
    var state = getHabitsState();
    localStorage.setItem('micro_habits',JSON.stringify(state));
    alert('Micro-practices saved to local browser note.');
  })}
  if(resetBtn){resetBtn.addEventListener('click',function(){
    var checks = document.querySelectorAll('.habits input[type="checkbox"]');
    checks.forEach(function(c){c.checked=false});
    localStorage.removeItem('micro_habits');
  })}
  restoreHabits();

  // Basic CTA: smooth scroll for internal anchors
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id = this.getAttribute('href').substring(1);
      var el = document.getElementById(id);
      if(el){el.scrollIntoView({behavior:'smooth'});}    
    });
  });
});"} 
